s = open(P, encoding='utf-8').read()
def rep(old, new, n=1):
    global s
    c = s.count(old)
    if c != n: sys.exit(f'COUNT {c} != {n} for: {old[:90]!r}')
    s = s.replace(old, new)
def line_starting(prefix):
    L = s.split('\n'); hits = [x for x in L if x.startswith(prefix)]
    if len(hits) != 1: sys.exit(f'LINE {len(hits)} for {prefix!r}')
    return hits[0]

